package com.procurement.service; import com.procurement.entity.*; import com.procurement.repository.*; import org.springframework.stereotype.Service;
@Service public class FarmerService { private final FarmerRepository farmers; private final UserRepository users; public FarmerService(FarmerRepository farmers,UserRepository users){this.farmers=farmers;this.users=users;} public Farmer me(String phone){User u=users.findByPhoneNumber(phone).orElseThrow();return farmers.findByUserId(u.getId()).orElseThrow(()->new IllegalArgumentException("Farmer profile not found"));}
 public Farmer update(String phone,String fullName,String village,String district,String state,String pincode,String alternatePhone){Farmer f=me(phone);if(fullName!=null)f.setFullName(fullName);if(village!=null)f.setVillage(village);if(district!=null)f.setDistrict(district);if(state!=null)f.setState(state);if(pincode!=null)f.setPincode(pincode);if(alternatePhone!=null)f.setAlternatePhone(alternatePhone);return farmers.save(f);}}
